// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // admissible domain: actor is a plain EOA (no code) that can receive ETH;
        // amount is a positive, realistic wei balance
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, 1000 ether);

        // deploy c so that the owner is the fuzzed EOA (withdraw transfers to Owner,
        // and a plain EOA safely accepts the transfer with 2300 gas)
        vm.prank(actor);
        c = new MultiplicatorX4();

        // fund the contract itself with the fuzzed amount
        vm.deal(address(c), amount);

        // owner drains the contract
        vm.prank(actor);
        c.withdraw();

        // GENERAL RULE: for any positive balance, after the owner's withdraw()
        // completes, NOTHING is left in the contract.
        assertTrue(address(c).balance == 0);
    }
}
